INSERT INTO picture_like_user (
    picture_id,
    user_id
)
VALUES (
    #{pictureId},
    #{userId}
)

mapper.delete:
DELETE FROM picture_like_user
WHERE picture_id = #{pictureId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM picture_like_user
WHERE picture_id = #{pictureId}

SELECT
    picture_id,
    created_at AS liked_at
FROM picture_like_user
WHERE user_id = #{userId}

    AND (
        created_at < #{cursorTime}
        OR (
            created_at = #{cursorTime}
            AND picture_id < #{cursorPictureId}
        )
    )

ORDER BY created_at DESC, picture_id DESC
LIMIT #{limit}
